import urllib.request,json
for genome in ['hg19','hg38']:
 for offset in [-1,0,1]:
  start=20014826+offset
  url=f'https://api.genome.ucsc.edu/getData/sequence?genome={genome}&chrom=chr1&start={start}&end={start+1}'
  try: print(genome, offset, json.load(urllib.request.urlopen(url))['dna'])
  except Exception as e: print(genome, offset, type(e).__name__, e)
PY"

